import sys
from collections.abc进口 import Iterable as Iterable

def read_input() -> Iterable[str]:
    return map(str.strip, sys.stdin)

def read_ints() -> Iterable[int]:
    return map(lambda x: int(x), read_input())

def read_tree(n: int) -> list[list[int]]:
    tree = [[] for _ in range(n)]
    for _ in range(n - 1):
        a, b = read_ints()
        tree[a - 1].append(b - 1)
        tree[b - 1].append(a - 1)
    return tree

def dfs(tree: list[list[int]], node: int, parent: int, color: list[int]) -> bool:
    if color[node] == -1:
        color[node] = 0
    for neighbor in tree[node]:
        if neighbor == parent:
            continue
        if color[neighbor] == -1:
            color[neighbor] = 1 - color[node]
            if not dfs(tree, neighbor, node, color):
                return False
        elif color[neighbor] == color[node]:
            return False
    return True

def find_permutation(tree: list[list[int]], n: int) -> list[int]:
    color = [-1] * n
    if not dfs(tree, 0, -1, color):
        return [-1]
    permutation = [0] * n
    for i in range(n):
        permutation[color[i]] = i + 1
    return permutation

def main():
    n = next(read_ints())
    tree = read_tree(n)
    permutation = find_permutation(tree, n)
    if permutation[0] == -1:
        print(-1)
    else:
        print(' '.join(map(str, permutation)))

if __name__ == '__main__':
    main()
